import{_ as t,o as r,c as o,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Conversion","description":"","frontmatter":{"title":"Conversion"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/conversion.md","filePath":"fr/projects/blocks-for-ha/conversion.md","lastUpdated":1793023597000}'),n={name:"fr/projects/blocks-for-ha/conversion.md"};function a(i,e,d,l,c,u){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="conversion" tabindex="-1">Conversion <a class="header-anchor" href="#conversion" aria-label="Permalink to &quot;Conversion&quot;">​</a></h1><p>Les conversions sont évaluées dans <strong>HA/Jinja</strong>. Elles ne reposent pas sur les coercitions de JavaScript. <a href="./blocks">Catalogue illustré</a>.</p><table tabindex="0"><thead><tr><th>Bloc</th><th>Résultat et limites</th></tr></thead><tbody><tr><td>Convertir en nombre</td><td><code>float()</code> HA exige une valeur numérique complète. Pas de préfixe <code>parseFloat</code> ni de valeur de secours implicite.</td></tr><tr><td>Convertir en booléen</td><td><code>bool()</code> HA reconnaît true/false, on/off, yes/no, 1/0. Valeur non reconnue : erreur.</td></tr><tr><td>Convertir en texte</td><td>Représentation Jinja ; booléens True/False. Ce n’est pas une sérialisation JSON.</td></tr><tr><td>Type de</td><td><code>typeof()</code> HA retourne les types Python : str, int, float, bool, dict, list, NoneType. HA ≥ 2023.4.</td></tr><tr><td>Convertir en date/heure</td><td>Texte ISO, secondes Unix ou millisecondes Unix. Préférer un fuseau explicite ; résultat en heure locale HA.</td></tr><tr><td>Formater date/heure</td><td>Objet date, texte ISO, formats d’heure/date, unités Unix, composantes de calendrier ou format personnalisé. Le raccord change selon le résultat.</td></tr><tr><td>Durée</td><td>Millisecondes ou secondes vers hh:mm:ss, hh:mm ou mm:ss. Fractions tronquées ; heures/minutes peuvent dépasser 24/60, signe conservé.</td></tr><tr><td>JSON vers valeur</td><td>Objet, liste ou valeur JSON simple. JSON invalide : erreur.</td></tr><tr><td>Valeur vers JSON</td><td>Sérialisation HA avec indentation facultative. Convertir les dates auparavant.</td></tr></tbody></table><p>Les formats personnalisés utilisent <strong>Python strftime</strong> : <code>%Y</code>, <code>%m</code>, <code>%d</code>, <code>%H</code>, <code>%M</code>, <code>%S</code>. Les formats de date ioBroker ne sont pas directement interchangeables.</p><p>Une conversion numérique produit un nombre à l’exécution. Elle peut alimenter calculs, variables et conditions de modèle, mais pas les seuils fixes des déclencheurs numériques. Les comparaisons de capteurs doivent convertir leurs états textuels explicitement.</p><p>Les allers-retours de projet/YAML conservent les formats pris en charge. JSONata n’est pas proposé sans moteur réellement disponible à l’exécution dans HA. <a href="https://www.home-assistant.io/docs/configuration/templating/" target="_blank" rel="noreferrer">Documentation des modèles HA</a> · <a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noreferrer">Référence ioBroker</a>.</p>',6)])])}const f=t(n,[["render",a]]);export{m as __pageData,f as default};
